// Zimmermann storefronts — 7 SFCC sites across 6 regions.
// TODO Mani to split US to 2 storefronts.
// Site IDs sourced from bkzk-002 BM (2026-06-13). See .docs/prd/regional.md for routing rules.
//
// EU domestic is split into 4 single-locale PWA sites (one per URL prefix) because PWA Kit maps
// one site alias → one URL prefix. All 4 share sfccSiteId: 'ZimmermannEU' so every API call
// still targets the single SFCC EU site. _app-config reads sfccSiteId when present.
module.exports = [
  // AU — root (no prefix), x-default hreflang, gated to AU/Oceania IPs
  {
    id: 'ZimmermannAU',
    l10n: {
      supportedCurrencies: ['AUD'],
      defaultCurrency: 'AUD',
      defaultLocale: 'en',
      supportedLocales: [
        {
          id: 'en',
          preferredCurrency: 'AUD',
        },
      ],
    },
  },
  // US — single site; domestic (/us/) via SFCC, international (/en-ca/) via Global-e
  {
    id: 'ZimmermannUS',
    l10n: {
      supportedCurrencies: ['USD'],
      defaultCurrency: 'USD',
      defaultLocale: 'en-US',
      supportedLocales: [
        {
          id: 'en-US',
          alias: 'us',
          preferredCurrency: 'USD',
        },
      ],
    },
  },
  // UK — /uk/ — SFCC checkout
  {
    id: 'ZimmermannUK',
    l10n: {
      supportedCurrencies: ['GBP'],
      defaultCurrency: 'GBP',
      defaultLocale: 'en-GB',
      supportedLocales: [
        {
          id: 'en-GB',
          alias: 'uk',
          preferredCurrency: 'GBP',
        },
      ],
    },
  },
  // EU domestic — four single-locale PWA sites, all backed by SFCC ZimmermannEU
  {
    id: 'ZimmermannEUen',
    sfccSiteId: 'ZimmermannEU',
    l10n: {
      supportedCurrencies: ['EUR'],
      defaultCurrency: 'EUR',
      defaultLocale: 'en-GB',
      supportedLocales: [
        {
          id: 'en-GB',
          alias: 'en-eu',
          preferredCurrency: 'EUR',
        },
      ],
    },
  },
  {
    id: 'ZimmermannEUfr',
    sfccSiteId: 'ZimmermannEU',
    l10n: {
      supportedCurrencies: ['EUR'],
      defaultCurrency: 'EUR',
      defaultLocale: 'fr',
      supportedLocales: [
        {
          id: 'fr',
          alias: 'fr-eu',
          preferredCurrency: 'EUR',
        },
      ],
    },
  },
  {
    id: 'ZimmermannEUit',
    sfccSiteId: 'ZimmermannEU',
    l10n: {
      supportedCurrencies: ['EUR'],
      defaultCurrency: 'EUR',
      defaultLocale: 'it',
      supportedLocales: [
        {
          id: 'it',
          alias: 'it-eu',
          preferredCurrency: 'EUR',
        },
      ],
    },
  },
  {
    id: 'ZimmermannEUes',
    sfccSiteId: 'ZimmermannEU',
    l10n: {
      supportedCurrencies: ['EUR'],
      defaultCurrency: 'EUR',
      defaultLocale: 'es',
      supportedLocales: [
        {
          id: 'es',
          alias: 'es-eu',
          preferredCurrency: 'EUR',
        },
      ],
    },
  },
  // EU international — /en-ch/ — Global-e checkout (non-EU Europe + Africa + ROW)
  {
    id: 'ZimmermannEUIntl',
    l10n: {
      supportedCurrencies: ['EUR'],
      defaultCurrency: 'EUR',
      defaultLocale: 'en-CH',
      supportedLocales: [
        {
          id: 'en-CH',
          alias: 'en-ch',
          preferredCurrency: 'EUR',
        },
      ],
    },
  },
  // HK — /hk/ — Global-e checkout (Asia-Pacific)
  {
    id: 'ZimmermannHK',
    l10n: {
      supportedCurrencies: ['HKD'],
      defaultCurrency: 'HKD',
      defaultLocale: 'en-HK',
      supportedLocales: [
        {
          id: 'en-HK',
          alias: 'hk',
          preferredCurrency: 'HKD',
        },
      ],
    },
  },
  // ME — /en-ae/ — Global-e checkout (Middle East)
  {
    id: 'ZimmermannME',
    l10n: {
      supportedCurrencies: ['AED'],
      defaultCurrency: 'AED',
      defaultLocale: 'en-AE',
      supportedLocales: [
        {
          id: 'en-AE',
          alias: 'en-ae',
          preferredCurrency: 'AED',
        },
      ],
    },
  },
];

